        server.publish([RommFirmware(id: 402, fileName: "scph5501.bin",
                                     fileSizeBytes: 524_288, isVerified: true,
                                     crcHash: nil, md5Hash: nil, sha1Hash: nil,
                                     missingFromFS: false,
                                     updatedAt: "2026-02-03T04:05:06")])
        server.transferHook = { _, _ in throw SentinelError() }
        let manager = try makeManager(cacheRoot: try tempDirectory(), server: server,
                                      catalog: catalog)

