    func testASymbolicLinkAtABIOSPathIsReplacedRatherThanWrittenThrough() async throws {
        let cacheRoot = try tempDirectory()
        let elsewhere = try tempDirectory()
        let target = elsewhere.appendingPathComponent("someone-elses-file.bin")
        // The link's target is a *valid* image, so the size and checksum checks
        // cannot be what refuses it: only "this is not a regular file" can.
        try SyntheticBIOS.usa.write(to: target)

        let server = liveShapedServer(SyntheticBIOS.catalog)
        let manager = try makeManager(cacheRoot: cacheRoot, server: server)
        let systemDirectory = manager.systemDirectory
        let path = systemDirectory.appendingPathComponent("scph5501.bin")
        try FileManager.default.createSymbolicLink(at: path, withDestinationURL: target)

        _ = try await manager.prepare(for: rom(regions: ["USA"]))

        XCTAssertEqual(server.requestedIDs, [102])
        XCTAssertEqual(bytes(path), SyntheticBIOS.usa)
        XCTAssertEqual((try FileManager.default.attributesOfItem(atPath: path.path))[.type]
                        as? FileAttributeType, .typeRegular)
        // Written to the link's own name, never through it.
        XCTAssertTrue(FileManager.default.fileExists(atPath: target.path))
    }

    func testASymbolicLinkIsNotABIOSHoweverGoodItsTargetIs() async throws {
        let cacheRoot = try tempDirectory()
        let elsewhere = try tempDirectory()
        // A link's own reported size is the length of the path it holds, so a
        // link to a valid image is normally rejected by the size check before
        // anything reads it. This one is planted with a target path exactly as
        // long as the image, which is the case where only "not a regular file"
        // can refuse it — and is a length an attacker who can plant a link can
        // choose freely.
        let target = try path(ofExactLength: Int(SyntheticBIOS.byteCount), under: elsewhere)
        try SyntheticBIOS.usa.write(to: target)
        XCTAssertEqual(target.path.utf8.count, Int(SyntheticBIOS.byteCount))

        let server = liveShapedServer(SyntheticBIOS.catalog)
        let manager = try makeManager(cacheRoot: cacheRoot, server: server)
        let path = manager.systemDirectory.appendingPathComponent("scph5501.bin")
        try FileManager.default.createSymbolicLink(at: path, withDestinationURL: target)
        // The trap is only a trap if the link looks like an installed image.
        let linkAttributes = try FileManager.default.attributesOfItem(atPath: path.path)
        XCTAssertEqual((linkAttributes[.size] as? NSNumber)?.int64Value,
                       SyntheticBIOS.byteCount)
        XCTAssertEqual(PS1FirmwareManager.digest(ofFileAt: path)?.md5,
                       SyntheticBIOS.catalog.usa.md5)

        _ = try await manager.prepare(for: rom(regions: ["USA"]))

        XCTAssertEqual(server.requestedIDs, [102])
        XCTAssertEqual((try FileManager.default.attributesOfItem(atPath: path.path))[.type]
                        as? FileAttributeType, .typeRegular)
    }

