    // MARK: - Errors a player reads

    func testAMissingBIOSErrorNamesTheExactFileAndOffersRetry() {
        let missing = PS1FirmwareError.firmwareNotOnServer(fileName: "scph5501.bin")
        XCTAssertEqual(missing.fileName, "scph5501.bin")
        XCTAssertTrue(missing.errorDescription?.contains("scph5501.bin") ?? false,
                      "\(missing.errorDescription ?? "nil")")
        XCTAssertTrue(missing.recoverySuggestion?.contains("scph5501.bin") ?? false,
                      "\(missing.recoverySuggestion ?? "nil")")
        XCTAssertTrue(missing.recoverySuggestion?.lowercased().contains("try again") ?? false,
                      "\(missing.recoverySuggestion ?? "nil")")

        for rejection: PS1FirmwareError.Rejection in [
            .missingFromStorage, .unverified, .wrongSize(byteCount: 1, expected: 524_288),
            .declaredChecksumMismatch(declared: String(repeating: "0", count: 32)),
        ] {
            let error = PS1FirmwareError.firmwareUnusable(fileName: "scph5502.bin",
                                                          rejection: rejection)
            XCTAssertEqual(error.fileName, "scph5502.bin")
            XCTAssertTrue(error.errorDescription?.contains("scph5502.bin") ?? false,
                          "\(rejection)")
            XCTAssertTrue(error.recoverySuggestion?.contains("scph5502.bin") ?? false,
                          "\(rejection)")
            XCTAssertTrue(error.recoverySuggestion?.lowercased().contains("try again") ?? false,
                          "\(rejection)")
        }

        let install = PS1FirmwareError.installFailed(fileName: "scph5500.bin", code: 21)
        XCTAssertTrue(install.errorDescription?.contains("scph5500.bin") ?? false)
        XCTAssertTrue(install.recoverySuggestion?.lowercased().contains("try again") ?? false)
    }

    // MARK: - Progress

    func testDownloadProgressComposesWithPackageProgress() async throws {
        let cacheRoot = try tempDirectory()
        let server = liveShapedServer(SyntheticBIOS.catalog)
        let manager = try makeManager(cacheRoot: cacheRoot, server: server)
        let recorder = ProgressRecorder()

        _ = try await manager.prepare(for: rom(regions: ["World"]),
                                      progress: { recorder.record($0) })

        let events = recorder.events
        // The same `PS1PreparationProgress` the package store reports, so one
        // screen can show BIOS retrieval and package assembly as one operation.
        let validating: [String] = events.compactMap {
            if case let .validating(label) = $0 { return label } else { return nil }
        }
        XCTAssertEqual(validating, ["scph5500.bin", "scph5501.bin", "scph5502.bin"])

        var labels: [String] = []
        var completedValues: [Int64] = []
        var totals: [Int64] = []
        for event in events {
            guard case let .downloading(label, completed, total) = event else { continue }
            labels.append(label)
            completedValues.append(completed)
            totals.append(total)
        }
        let total = SyntheticBIOS.byteCount * 3
        XCTAssertFalse(completedValues.isEmpty)
        XCTAssertEqual(Set(totals), [total])
        XCTAssertTrue(completedValues.allSatisfy { $0 >= 0 && $0 <= total })
        XCTAssertEqual(completedValues, completedValues.sorted(),
                       "cumulative progress must never go backwards")
        XCTAssertEqual(completedValues.last, total)
        XCTAssertEqual(Set(labels), ["scph5500.bin", "scph5501.bin", "scph5502.bin"])
    }

    func testAFullyCachedPreparationReportsValidationAndNoDownloads() async throws {
        let cacheRoot = try tempDirectory()
        let server = FakeFirmwareServer()
        let manager = try makeManager(cacheRoot: cacheRoot, server: server)
        let systemDirectory = manager.systemDirectory
        try installValid(SyntheticBIOS.catalog[.usa], in: systemDirectory)
        let recorder = ProgressRecorder()

        _ = try await manager.prepare(for: rom(regions: ["USA"]),
                                      progress: { recorder.record($0) })

        XCTAssertTrue(recorder.events.allSatisfy {
            if case .validating = $0 { return true } else { return false }
        })
        XCTAssertEqual(server.listCalls, [])
    }

    // MARK: - Helpers

    private func assertPrepareFails(_ manager: PS1FirmwareManager,
                                    regions: [String],
                                    with expected: PS1FirmwareError,
                                    file: StaticString = #filePath,
                                    line: UInt = #line) async {
        do {
            _ = try await manager.prepare(for: rom(regions: regions))
            XCTFail("expected \(expected)", file: file, line: line)
        } catch let error as PS1FirmwareError {
            XCTAssertEqual(error, expected, file: file, line: line)
        } catch {
            XCTFail("unexpected error \(error)", file: file, line: line)
        }
    }
}

/// Collects progress from whatever thread reports it.
private final class ProgressRecorder: @unchecked Sendable {
    private let lock = NSLock()
    private var storage: [PS1PreparationProgress] = []

    func record(_ event: PS1PreparationProgress) {
        lock.lock(); storage.append(event); lock.unlock()
    }

    var events: [PS1PreparationProgress] {
        lock.lock(); defer { lock.unlock() }; return storage
    }
}
